  const css0 = `.cp{font:400 16px/1.45 ${B};color:#fff;background:#020816;-webkit-font-smoothing:antialiased;overflow-x:clip}
.cp button{font:inherit;color:inherit;cursor:pointer;border:0;background:none;padding:0}
.cp-hd{position:sticky;top:0;z-index:30;height:0}
.cp-ann{height:40px;background:#2f7cf4;display:flex;align-items:center;justify-content:center;font-weight:600;font-size:16px;position:relative;cursor:pointer}.cp-ann .x{position:absolute;right:16px;top:9px;font-size:18px;opacity:.9}
.cp-nav{display:flex;align-items:center;gap:14px;padding:20px 30px 0;transition:padding .5s cubic-bezier(.5,0,.2,1)}
.cp-cap{display:flex;align-items:center;height:60px;border-radius:18px;border:1px solid transparent;transition:all .5s cubic-bezier(.5,0,.2,1);padding:0 10px}
.cp-l{flex:1}.cp-split .cp-l{flex:0 0 auto}
.cp-split .cp-cap{background:#0d1a33a6;border-color:#ffffff14;backdrop-filter:blur(18px) saturate(1.4);-webkit-backdrop-filter:blur(18px) saturate(1.4);box-shadow:0 10px 40px #0007}
.cp-logo{width:32px;height:32px;border-radius:8px;background:#fff;display:grid;place-items:center;flex:none}
.cp-nm{font:600 19px ${B};letter-spacing:-.01em;white-space:nowrap;overflow:hidden;max-width:180px;margin-left:13px;transition:max-width .5s,opacity .3s,margin .5s}.cp-split .cp-nm{max-width:0;opacity:0;margin-left:0}
.cp-links{display:flex;gap:24px;margin:0 auto;font-size:17px;font-weight:500;transition:margin .5s}.cp-split .cp-links{margin:0 12px 0 24px}.cp-links a{cursor:pointer;opacity:.92}.cp-links a:hover{opacity:1;text-decoration:underline;text-underline-offset:5px}
.cp-r{gap:8px;padding:0 8px}.cp-r .li{padding:10px 16px;font-size:17px;font-weight:500}.cp-gs{background:#fff!important;color:#071024!important;border-radius:12px!important;padding:10px 12px!important;font-weight:600!important;font-size:17px!important;box-shadow:0 2px 10px #0004}
.cp-split .cp-r .cp-gs{background:#fff!important}
.cp-hero{position:relative;height:max(760px,var(--vh));overflow:hidden;padding-top:40px;box-sizing:border-box}
.cp-hero::before{content:'';position:absolute;left:50%;top:48%;width:900px;height:520px;transform:translate(-50%,-50%);background:radial-gradient(closest-side,#16306a55,#0000)}
.cp-p{position:absolute;width:0;height:0;will-change:transform;transition:transform .25s ease-out}
.cp-pi{position:absolute;left:0;top:0;transform:translate(-50%,-50%) rotate(var(--r));animation:cpf var(--d) ease-in-out infinite alternate}
.cp-pi>div{display:flex;align-items:center;gap:14px;height:82px;padding:0 34px 0 22px;border-radius:44px;font:800 27px ${D};letter-spacing:.04em;white-space:nowrap;color:#ffffffd9;filter:blur(var(--b));box-shadow:inset 0 2px 0 #ffffff40,inset 0 -6px 14px #00000030,0 20px 40px #0006;text-shadow:0 1px 2px #0003}
.cp-pi span{font-size:40px;filter:saturate(1.1)}
@keyframes cpf{from{translate:0 -9px}to{translate:0 9px}}
.cp-h1{position:relative;text-align:center;margin:110px auto 0;font:700 128px/.94 ${D};letter-spacing:-.025em;max-width:1000px;background:linear-gradient(180deg,#fbfcff 0%,#d6dbe5 38%,#9ba3b4 70%,#c7ccd7 100%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 4px 30px #0009)}
.cp-sub{position:relative;text-align:center;font:400 27px/1.27 ${B};color:#c6cfdf;margin:48px 0 34px;letter-spacing:-.005em}
.cp-cta{display:flex;align-items:center;gap:12px;margin:0 auto;position:relative;background:linear-gradient(#3b7bff,#1f5ef0)!important;padding:13px 26px 13px 18px!important;border-radius:16px!important;font:600 23px ${B}!important;box-shadow:0 0 0 1px #6b9bff66 inset,0 10px 40px #2f6df655}.cp-cta:hover{filter:brightness(1.1)}
.cp-mock{position:relative;width:1080px;max-width:calc(100% - 80px);height:560px;margin:20px auto 0}
.cp-dk{position:absolute;left:0;top:0;width:82%;height:470px;border-radius:16px;border:1px solid #1d2b4a;background:#060f22;overflow:hidden;display:grid;grid-template-columns:150px 1fr;box-shadow:0 30px 80px #000a}
.cp-sb{border-right:1px solid #13213d;padding:40px 12px;font-size:10.5px;color:#9fb0cc;display:flex;flex-direction:column;gap:12px}.cp-sb b{color:#fff;background:#1d4fd6;border-radius:6px;padding:4px 8px;font-weight:600}
.cp-dg{display:grid;grid-template-columns:1.4fr 1fr;gap:12px;padding:34px 16px 16px}.cp-c{background:#0a1630;border:1px solid #14254a;border-radius:12px;padding:14px;font-size:11px;color:#9fb0cc;position:relative}.cp-c h5{margin:0 0 6px;font:600 11.5px ${B};color:#dbe4f5}
.cp-c .big{font:700 22px ${D};color:#fff;text-align:center}
.cp-ph{position:absolute;right:0;top:20px;width:250px;height:520px;border-radius:38px;border:7px solid #1a2238;background:#071024;box-shadow:0 30px 80px #000c;padding:22px 14px;box-sizing:border-box;font-size:10px;color:#9fb0cc}
.cp-ring{display:flex;justify-content:space-between;margin-top:12px}.cp-ring div{text-align:center;font-size:9px}.cp-ring svg{display:block;margin:0 auto 4px}
.cp-sec{max-width:1040px;margin:0 auto;padding:110px 30px 30px}.cp-h2{font:700 64px/1.02 ${D};letter-spacing:-.02em;text-align:center;margin:0 0 50px;background:linear-gradient(180deg,#fff,#a6aebe);-webkit-background-clip:text;background-clip:text;color:transparent}
.cp-bento{display:grid;grid-template-columns:1fr 1fr;gap:18px}.cp-b{background:linear-gradient(#071430,#050e22);border:1px solid #13244a;border-radius:24px;padding:30px;min-height:300px;overflow:hidden;position:relative}.cp-b.w{grid-column:1/-1;display:grid;grid-template-columns:1fr 1.05fr;gap:30px}
.cp-b h3{font:600 26px/1.15 ${B};margin:0 0 10px;letter-spacing:-.01em}.cp-b p{color:#7f93b6;font-size:17px;margin:0}
.cp-rv{background:#081733;border:1px solid #1b2f57;border-radius:18px;padding:18px 22px 14px;box-shadow:0 0 60px #2f6df622}.cp-rv header{display:flex;justify-content:space-between;font-size:15px;font-weight:600;margin-bottom:14px}.cp-rv header a{color:#5d7fb8;font-weight:500;cursor:pointer}
.cp-rv small{display:block;font:700 11px ${B};letter-spacing:.06em;color:#5d7fb8;margin-bottom:6px}
.cp-tr{display:grid;grid-template-columns:22px 1fr auto 82px;align-items:center;gap:8px;height:38px;font-size:15px;transition:opacity .35s,transform .35s,height .35s .1s;cursor:pointer;overflow:hidden}
.cp-tr .ck{width:18px;height:18px;border-radius:50%;border:1.5px solid #2a4170;display:grid;place-items:center;font-size:11px;color:transparent;transition:all .25s}.cp-tr.done .ck{background:#22c55e;border-color:#22c55e;color:#04210f}
.cp-tr.done .nm{color:#5d7fb8;text-decoration:line-through}.cp-tr.gone{opacity:0;transform:translateX(30px);height:0}
.cp-tag{font:700 11px ${B};letter-spacing:.05em;padding:4px 10px;border-radius:99px;display:flex;gap:5px;align-items:center}.cp-tr .am{text-align:right;font-variant-numeric:tabular-nums}
.cp-mr{width:100%;margin-top:12px;padding:11px!important;border-radius:10px!important;background:#10234a!important;font:700 12.5px ${B}!important;letter-spacing:.06em;color:#9fc0ff!important;transition:background .2s}.cp-mr:hover{background:#163063!important}.cp-mr:disabled{opacity:.6;cursor:default}
.cp-done{text-align:center;padding:28px 0 12px;font-size:16px;color:#9fb0cc;display:none}.cp-done b{display:block;font:600 22px ${B};color:#fff;margin-bottom:4px}.cp-done a{color:#7fa6ff;cursor:pointer;text-decoration:underline;font-size:14px}
.cp-tagch{position:absolute;right:62px;top:205px;background:#22c55e;color:#04210f;font:700 13px ${B};padding:3px 9px;border-radius:7px}
.cp-bars{display:flex;align-items:flex-end;gap:16px;height:110px;margin:30px 0 0 20px;position:relative}.cp-bars div{width:16px;border-radius:5px 5px 2px 2px}.cp-bars::after{content:'$80.00';position:absolute;right:-10px;top:30px;background:#20365e;font:600 13px ${B};padding:3px 8px;border-radius:6px}
.cp-mq{display:flex;gap:10px;margin-top:40px;width:max-content;animation:cpm 22s linear infinite}.cp-mq span{background:#0c1d3d;border:1px solid #1b2f57;border-radius:12px;padding:10px 14px;font-size:15px;white-space:nowrap}.cp-mq b{color:#3ddc84;margin-left:8px}.cp-mq b.n{color:#ff6b6b}
@keyframes cpm{to{transform:translateX(-50%)}}
.cp-light{margin:90px 24px 0;background:#eef1f6;border-radius:44px;color:#0b1220;padding:20px 0 80px}.cp-light .cp-h2{background:linear-gradient(180deg,#0b1220,#48536a);-webkit-background-clip:text;background-clip:text}
.cp-light .cp-b{background:#fff;border:0;box-shadow:0 2px 0 #0000000a,0 12px 40px #0b12200d}.cp-light .cp-b p{color:#6b7790}
.cp-seg{display:flex;gap:4px;margin:14px 0}.cp-seg button{padding:4px 10px;border-radius:8px;font-size:13px;color:#6b7790;font-weight:600}.cp-seg button.on{background:#eef1f6;color:#0b1220}
.cp-acc{display:grid;grid-template-columns:28px 1fr auto 70px;gap:10px;align-items:center;font-size:14px;padding:8px 0}.cp-acc i{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;color:#fff;font:700 12px ${B};font-style:normal}.cp-acc small{display:block;color:#8a94a8;font-size:11.5px}
.cp-pct{font:700 11.5px ${B};padding:2px 8px;border-radius:99px;background:#e6f8ec;color:#16a34a}.cp-pct.n{background:#fdecec;color:#dc2626}
.cp-tk{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:20px}.cp-tk div{border:1px solid #e4e8ef;border-radius:14px;padding:12px;font-size:13px}.cp-tk b{display:block;font-size:14px}
.cp-al{display:grid;grid-template-columns:80px 1fr;gap:12px 14px;align-items:center;margin-top:24px;font-size:14px;font-weight:600}.cp-al i{height:6px;border-radius:9px;background:#e4e8ef;position:relative;overflow:hidden}.cp-al i b{position:absolute;inset:0 auto 0 0;background:#2f6df6;border-radius:9px;transition:width .8s}
.cp-ft{text-align:center;padding:110px 20px 120px}.cp-ft p{color:#8ea0c0;font-size:19px;max-width:560px;margin:0 auto 30px}`;
