  const N = ['BOOT', 'SPOON', 'CHAIR', 'TICKET', 'LAWSUIT', 'CANDLE', 'SOCK', 'BRICK', 'STAMP', 'BAG', 'TOASTER', 'MAP', 'ALARM', 'COIN', 'HAT', 'PUZZLE', 'APP', 'BOT', 'RING', 'TROPHY', 'MASK', 'PILL', 'SNEAKER', 'BELT'];
