    t0.day = from; draw();
    const t1 = tasks.find((t) => t.text.includes('colors'));
    const c0 = t1.color; t1.color = '#b8e0ff'; draw(); o.push(`color ${c0}→${t1.color}`); t1.color = c0; draw();
