  const el = h('div.su');
  let prompt = '', advanced = false, playing = -1;
  const ph = h('div.su-ph', {}, 'Chat to make music');
  const createBtn = h('button.su-create', {}, '♪ Create');
  const diceBtn = h('button.dice', { title: 'Random' }, '⚀');
